// Simple Space Drift game
// Canvas with id="game" is expected in the HTML.

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  const ship = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    angle: 0,
    vx: 0,
    vy: 0,
    radius: 10,
    alive: true,
  };

  let fuel = 100;
  let score = 0;
  const keys = { ArrowLeft: false, ArrowRight: false, ArrowUp: false };

  // generate asteroids
  const asteroids = [];
  for (let i = 0; i < 8; i++) {
    asteroids.push({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      vx: (Math.random() - 0.5) * 1.5,
      vy: (Math.random() - 0.5) * 1.5,
      radius: 15 + Math.random() * 20,
    });
  }

  // generate energy orbs
  const orbs = [];
  for (let i = 0; i < 5; i++) {
    orbs.push({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      radius: 8,
    });
  }

  function drawShip() {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(12, 0);
    ctx.lineTo(-8, -8);
    ctx.lineTo(-8, 8);
    ctx.closePath();
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.restore();
  }

  function draw() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // asteroids
    ctx.fillStyle = 'gray';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });

    // orbs
    ctx.fillStyle = 'yellow';
    orbs.forEach(o => {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.radius, 0, Math.PI * 2);
      ctx.fill();
    });

    if (ship.alive) drawShip();

    // UI
    ctx.fillStyle = 'white';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Fuel: ${fuel.toFixed(0)}`, 10, 40);
  }

  function update(dt) {
    // handle input
    if (keys.ArrowLeft) ship.angle -= 0.04;
    if (keys.ArrowRight) ship.angle += 0.04;
    if (keys.ArrowUp && fuel > 0) {
      const thrust = 0.1;
      ship.vx += Math.cos(ship.angle) * thrust;
      ship.vy += Math.sin(ship.angle) * thrust;
      fuel -= 0.03 * dt;
    }

    // move ship
    ship.x += ship.vx * dt;
    ship.y += ship.vy * dt;
    // wrap around edges
    if (ship.x < 0) ship.x += canvas.width;
    if (ship.x > canvas.width) ship.x -= canvas.width;
    if (ship.y < 0) ship.y += canvas.height;
    if (ship.y > canvas.height) ship.y -= canvas.height;

    // move asteroids
    asteroids.forEach(a => {
      a.x += a.vx * dt;
      a.y += a.vy * dt;
      if (a.x < 0) a.x += canvas.width;
      if (a.x > canvas.width) a.x -= canvas.width;
      if (a.y < 0) a.y += canvas.height;
      if (a.y > canvas.height) a.y -= canvas.height;
    });

    // check collisions with asteroids
    for (const a of asteroids) {
      const dx = ship.x - a.x;
      const dy = ship.y - a.y;
      const dist = Math.hypot(dx, dy);
      if (dist < ship.radius + a.radius) {
        ship.alive = false;
        break;
      }
    }

    // check collisions with orbs
    for (let i = orbs.length - 1; i >= 0; i--) {
      const o = orbs[i];
      const dx = ship.x - o.x;
      const dy = ship.y - o.y;
      if (Math.hypot(dx, dy) < ship.radius + o.radius) {
        fuel = Math.min(100, fuel + 20);
        score += 10;
        orbs.splice(i, 1);
      }
    }

    // lose condition fuel
    if (fuel <= 0) ship.alive = false;
  }

  let last = performance.now();
  function loop(now) {
    const dt = (now - last) / 16.666; // normalize to ~60fps units
    last = now;
    if (ship.alive) {
      update(dt);
      draw();
      requestAnimationFrame(loop);
    } else {
      draw();
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2 - 120, canvas.height / 2);
    }
  }

  // input handlers
  window.addEventListener('keydown', e => {
    if (e.key in keys) keys[e.key] = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key in keys) keys[e.key] = false;
  });

  // start
  requestAnimationFrame(loop);
})();
